use serde_json::{json,Value};
use std::{fs,io::{BufRead,BufReader,Read,Write},net::{TcpListener,TcpStream},os::unix::fs::PermissionsExt,path::PathBuf,process::{Child,Command,Stdio},time::{Duration,Instant}};
struct Service{child:Child,root:PathBuf,port:u16}
impl Service{
 fn start()->Self{let mut b=[0;8];getrandom::getrandom(&mut b).unwrap();let root=std::env::current_dir().unwrap().join("target").join(format!("test-{:x}",u64::from_ne_bytes(b)));fs::create_dir_all(&root).unwrap();let helper=root.join("helper");fs::write(&helper,"#!/bin/sh\nprintf '{\"written\":true,\"verified\":true,\"representation\":\"file-url\"}\\n'\n").unwrap();fs::set_permissions(&helper,fs::Permissions::from_mode(0o700)).unwrap();let mut child=Command::new(env!("CARGO_BIN_EXE_jpeg-clipboard-service")).args(["--port","0","--no-open","--json-events","--origin","https://compress.example/path","--cache-dir"]).arg(root.join("cache")).arg("--helper").arg(helper).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();let mut line=String::new();BufReader::new(child.stdout.take().unwrap()).read_line(&mut line).unwrap();let v:Value=serde_json::from_str(&line).unwrap();assert_eq!(v["event"],"ready","{v}");let port=v["endpoint"].as_str().unwrap().rsplit(':').next().unwrap().parse().unwrap();Self{child,root,port}}
 fn request(&self,method:&str,path:&str,body:&[u8],origin:&str,kind:&str)->(u16,Vec<u8>,String){let mut s=TcpStream::connect(("127.0.0.1",self.port)).unwrap();s.set_read_timeout(Some(Duration::from_secs(4))).unwrap();let head=format!("{method} {path} HTTP/1.1\r\nHost: 127.0.0.1:{}\r\nOrigin: {origin}\r\nContent-Type: {kind}\r\nContent-Length: {}\r\n\r\n",self.port,body.len());s.write_all(head.as_bytes()).unwrap();s.write_all(body).unwrap();let mut out=Vec::new();s.read_to_end(&mut out).unwrap();let pos=out.windows(4).position(|b|b==b"\r\n\r\n").unwrap();let head=String::from_utf8(out[..pos].to_vec()).unwrap();let status=head.split_whitespace().nth(1).unwrap().parse().unwrap();(status,out[pos+4..].to_vec(),head)}
 fn post(&self,path:&str,body:&[u8],kind:&str)->(u16,Value){let (status,bytes,_)=self.request("POST",path,body,&format!("http://127.0.0.1:{}",self.port),kind);(status,serde_json::from_slice(&bytes).unwrap())}
}
impl Drop for Service{fn drop(&mut self){drop(self.child.stdin.take());let start=Instant::now();while self.child.try_wait().unwrap().is_none(){if start.elapsed()>Duration::from_secs(3){self.child.kill().unwrap();panic!("EOF shutdown hung")}std::thread::sleep(Duration::from_millis(10))}assert_eq!(self.child.wait().unwrap().code(),Some(0));assert!(self.root.starts_with(std::env::current_dir().unwrap().join("target")));fs::remove_dir_all(&self.root).unwrap();}}
fn fixture(names:&[&str])->Vec<u8>{// Minimal stored ZIP builder permits duplicate records, unlike ZipWriter.
 let mut out=Vec::new();let mut central=Vec::new();for name in names{let offset=out.len() as u32;let n=name.as_bytes();out.extend(b"PK\x03\x04");out.extend(20u16.to_le_bytes());out.extend(0x800u16.to_le_bytes());out.extend([0u8;16]);out.extend((n.len() as u16).to_le_bytes());out.extend(0u16.to_le_bytes());out.extend(n);central.extend(b"PK\x01\x02");central.extend(20u16.to_le_bytes());central.extend(20u16.to_le_bytes());central.extend(0x800u16.to_le_bytes());central.extend([0u8;18]);central.extend((n.len() as u16).to_le_bytes());central.extend([0u8;12]);central.extend(offset.to_le_bytes());central.extend(n);}let offset=out.len() as u32;out.extend(&central);out.extend(b"PK\x05\x06");out.extend([0;4]);out.extend((names.len()as u16).to_le_bytes());out.extend((names.len()as u16).to_le_bytes());out.extend((central.len()as u32).to_le_bytes());out.extend(offset.to_le_bytes());out.extend(0u16.to_le_bytes());out}
#[test]fn origins_assets_and_http_framing(){let s=Service::start();let (status,page,head)=s.request("GET","/",b"","","text/plain");assert_eq!(status,200);let page=String::from_utf8(page).unwrap();assert!(page.contains("const KV_SIMULATE = true"));assert!(!page.contains("googletagmanager.com"));assert!(!page.contains("hm.baidu.com"));assert!(page.contains("<script nonce="));assert!(head.contains("Content-Security-Policy:"));for origin in ["null","https://evil.example",""]{assert_eq!(s.request("POST","/api/health",b"{}",origin,"application/json").0,403)}assert_eq!(s.request("POST","/api/health",b"{}","https://compress.example","application/json").0,200);assert_eq!(s.request("GET","/",b"","https://evil.example","text/plain").0,403);assert_eq!(s.post("/api/clipboard/file",br#"{"fileId":"bad"}"#,"application/json").0,404);
 let mut raw=TcpStream::connect(("127.0.0.1",s.port)).unwrap();write!(raw,"POST /api/health HTTP/1.1\r\nHost: 127.0.0.1:{}\r\nHost: evil\r\n\r\n",s.port).unwrap();let mut v=Vec::new();raw.read_to_end(&mut v).unwrap();assert!(v.is_empty());}
#[test]fn jpeg_exact_bytes_hash_and_fake_clipboard(){let s=Service::start();let jpeg=b"\xff\xd8\xffTEST\xff\xd9";let (status,v)=s.post("/api/files",jpeg,"image/jpeg");assert_eq!(status,201,"{v}");let file=s.root.join("cache").join(v["name"].as_str().unwrap());assert_eq!(fs::read(file).unwrap(),jpeg);use sha2::{Digest,Sha256};assert_eq!(v["sha256"],format!("{:x}",Sha256::digest(jpeg)));assert_eq!(v["fileId"].as_str().unwrap().len(),32);assert_eq!(s.post("/api/clipboard/file",json!({"fileId":v["fileId"]}).to_string().as_bytes(),"application/json").1["verified"],true);assert_eq!(s.post("/api/files",b"not jpeg","image/jpeg").0,400);assert_eq!(s.post("/api/files",jpeg,"text/plain").0,415);}
#[test]fn zip_metadata_original_bytes_and_security(){let s=Service::start();let zip=fixture(&["照片/a.jpg","照片/b.txt"]);let (status,v)=s.post("/api/archives",&zip,"application/zip");assert_eq!(status,201,"{v}");assert_eq!(v["name"],"照片.zip");assert_eq!(fs::read(s.root.join("cache").join(v["fileId"].as_str().unwrap()).join("照片.zip")).unwrap(),zip);for name in ["../escape","/abs","C:/drive","root\\bad","root/../bad","root/./bad"]{assert_eq!(s.post("/api/archives",&fixture(&[name]),"application/zip").0,400,"{name}")}assert_eq!(s.post("/api/archives",&fixture(&["x","x"]),"application/zip").0,400);let mut encrypted=fixture(&["x"]);let c=encrypted.windows(4).position(|b|b==b"PK\x01\x02").unwrap();encrypted[c+8]=1;assert_eq!(s.post("/api/archives",&encrypted,"application/zip").0,400);let mut expanded=fixture(&["x"]);expanded[c+24..c+28].copy_from_slice(&250000001u32.to_le_bytes());assert_eq!(s.post("/api/archives",&expanded,"application/zip").0,400);}
#[test]fn stalled_upload_does_not_block_health_or_eof(){let s=Service::start();let mut stalled=TcpStream::connect(("127.0.0.1",s.port)).unwrap();write!(stalled,"POST /api/files HTTP/1.1\r\nHost: 127.0.0.1:{}\r\nOrigin: http://127.0.0.1:{}\r\nContent-Type: image/jpeg\r\nContent-Length: 100\r\n\r\nX",s.port,s.port).unwrap();let mut header=TcpStream::connect(("127.0.0.1",s.port)).unwrap();header.write_all(b"GET / HTTP/1.1\r\n").unwrap();let start=Instant::now();assert_eq!(s.post("/api/health",b"{}","application/json").0,200);assert!(start.elapsed()<Duration::from_secs(2));drop(s);drop(stalled);drop(header);}
#[test]fn symlinks_and_cache_limit_fail_closed(){let s=Service::start();let outside=s.root.join("outside");fs::create_dir(&outside).unwrap();std::os::unix::fs::symlink(&outside,s.root.join("cache/link")).unwrap();assert_eq!(s.post("/api/files",b"\xff\xd8\xff\xff\xd9","image/jpeg").0,400);fs::remove_file(s.root.join("cache/link")).unwrap();let f=fs::File::create(s.root.join("cache/full.jpg")).unwrap();f.set_len(1_000_000_000).unwrap();assert_eq!(s.post("/api/files",b"\xff\xd8\xff\xff\xd9","image/jpeg").0,507);}
#[test]fn all_default_ports_busy_errors(){let mut listeners=Vec::new();for p in 48731..=48735{match TcpListener::bind(("127.0.0.1",p)){Ok(l)=>listeners.push(l),Err(e)if e.kind()==std::io::ErrorKind::AddrInUse=>(),Err(e)=>panic!("{e}")}}let s=Service::start();let output=Command::new(env!("CARGO_BIN_EXE_jpeg-clipboard-service")).arg("--cache-dir").arg(s.root.join("cache2")).arg("--helper").arg(s.root.join("helper")).arg("--no-open").output().unwrap();assert!(!output.status.success());let v:Value=serde_json::from_slice(&output.stdout).unwrap();assert_eq!(v["event"],"error");assert!(v["message"].as_str().unwrap().contains("48731"));}
